import math
from itertools import combinations

def gcd(a, b):
    return math.gcd(a, b)

def gcd3(a, b, c):
    return math.gcd(a, gcd(b, c))

def is_good_set(U):
    u1, u2, u3 = U

    # Constraint 1: GCD of any three distinct elements is 1. Since |U|=3, we check GCD(u1, u2, u3)
    if gcd3(u1, u2, u3) != 1:
        return False

    # Constraint 2: For any two distinct elements, there exists another element that is a divisor of their product.
    # The elements are u1, u2, u3.

    # Pair (u1, u2): must be divisible by u3
    if u1 * u2 % u3 != 0:
        return False

    # Pair (u1, u3): must be divisible by u2
    if u1 * u3 % u2 != 0:
        return False

    # Pair (u2, u3): must be divisible by u1
    if u2 * u3 % u1 != 0:
        return False

    return True

good_products = set()
elements = list(range(2, 16)) # Elements must be up to 15. We established u1 > 1.

for U in combinations(elements, 3):
    if is_good_set(U):
        m = U[0] * U[1] * U[2]
        good_products.add(m)

# Sort and print the results
sorted_products = sorted(list(good_products))
print(f"Found {len(sorted_products)} good products (m).")
print("The list of good products is:")
print(sorted_products)

