import itertools

def generate_products(limit):
    primes = []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    products = set()
    for p1, p2, p3 in itertools.combinations(primes, 3):
        products.add(p1 * p2 * p3)

    return sorted(list(products))

# Estimate a limit. The 20th product is likely small.
# The 20th product of three primes is around 200-300. Let's check up to 3000 to be safe.
products = generate_products(3000)
print(f"The 20th smallest product of three distinct primes is: {products[19]}")
print("The first 20 such products are:")
print(products[:20])

